{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "In each month, is the warehouse capacity limit of 500 units applied to the stock level at the end of that month (after that month's purchases and sales are settled)?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of when the capacity limit is applied."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units can be purchased or sold in a given month, or are purchases and sales in each month unlimited as long as the end-of-month stock stays within 0 to 500 units?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of monthly transaction limits versus unlimited transactions subject to stock constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the stock allowed to go negative within a month (i.e., can you sell more than you have on hand and make up the difference with that month's purchases), or must stock never drop below zero at any point?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether stock can go negative, presented as a binary alternative."
}

